/**
 * Python exception look-alikes.
 *
 * The reference implementation lets several exceptions escape to the top level
 * (`TypeError`, `AttributeError`, `ZeroDivisionError`, ...).  When that happens
 * CPython prints a traceback on stderr and exits with status 1 without ever
 * printing the error count, so the only thing we have to reproduce is "raise
 * something that aborts the run".  Keeping the Python exception name around
 * makes the stderr output readable and lets the entry point mimic the
 * `<type>: <message>` last line of a traceback.
 */

export class PythonError extends Error {
  constructor(pyType, message) {
    super(message);
    this.name = pyType;
    this.pyType = pyType;
  }

  toString() {
    return this.message ? `${this.pyType}: ${this.message}` : this.pyType;
  }
}

const define = (pyType) => class extends PythonError {
  constructor(message = '') {
    super(pyType, message);
  }
};

export const TypeError_ = define('TypeError');
export const AttributeError = define('AttributeError');
export const ValueError = define('ValueError');
export const KeyError = define('KeyError');
export const IndexError = define('IndexError');
export const OverflowError = define('OverflowError');
export const ZeroDivisionError = define('ZeroDivisionError');
export const RecursionError = define('RecursionError');
export const ReError = define('re.error');

export class JSONDecodeError extends PythonError {
  constructor(msg, doc, pos) {
    const lineno = doc.slice(0, pos).split('\n').length;
    const colno = pos - (doc.lastIndexOf('\n', pos - 1) + 1) + 1;
    super('json.decoder.JSONDecodeError', `${msg}: line ${lineno} column ${colno} (char ${pos})`);
    this.pos = pos;
  }
}

