input.content:
/**
 * Value model.
 *
 * A parsed JSON document is represented with ordinary JavaScript values
 * (`null`, booleans, numbers, strings, arrays, plain objects) so that the
 * validator code reads like the original Python.  Two pieces of information
 * that Python keeps for free are attached to every container through a hidden
 * symbol instead:
 *
 *   - `keys`   the *insertion* order of the object members.  Python `dict`s
 *              iterate in insertion order while JS objects hoist keys that look
 *              like array indices (`{"10":…,"2":…}` iterates `2` then `10`),
 *              and keyword iteration order decides which error/exception the
 *              reference implementation hits first.
 *   - `floats` which members came from a *float* literal (`3.0`, `1e2`).  Python
 *              distinguishes `int` from `float` and `multipleOf` picks a
 *              different algorithm for each, so `{"multipleOf": 3}` and
 *              `{"multipleOf": 3.0}` do not always agree.
 */

export const META = Symbol('pyjson.meta');

export function attachMeta(container, meta) {
  Object.defineProperty(container, META, { value: meta, enumerable: false });
  return container;
}

export const isDict = (value) =>
  typeof value === 'object' && value !== null && !Array.isArray(value);

export const isList = Array.isArray;
export const isStr = (value) => typeof value === 'string';
export const isBool = (value) => typeof value === 'boolean';
export const isNum = (value) => typeof value === 'number';

/** Object members in Python `dict` iteration order. */
export function keysOf(dict) {
  const meta = dict[META];
  return meta && meta.keys ? meta.keys : Object.keys(dict);
}

/** `[key, value]` pairs in Python `dict` iteration order (`dict.items()`). */
export function itemsOf(dict) {
  return keysOf(dict).map((key) => [key, dict[key]]);
}

/** True when `container[key]` was written as a Python `float` literal. */
export function isFloatMember(container, key) {
  const meta = container == null ? undefined : container[META];
  return Boolean(meta && meta.floats && meta.floats.has(key));
}

/** The name Python would use for this value's type, for exception messages. */
export function typeName(value) {
  if (value === null) return 'NoneType';
  switch (typeof value) {
    case 'boolean': return 'bool';
    case 'string': return 'str';
    case 'number': return Number.isInteger(value) ? 'int' : 'float';
    case 'object': return Array.isArray(value) ? 'list' : 'dict';
    default: return typeof value;
  }
}

/** Short `repr`-ish rendering, only ever used inside error messages. */
export function repr(value) {
  if (value === null) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (isStr(value)) return `'${value.replace(/'/g, "\\'")}'`;
  if (isList(value)) return `[${value.map(repr).join(', ')}]`;
  if (isDict(value)) {
    return `{${keysOf(value).map((k) => `${repr(k)}: ${repr(value[k])}`).join(', ')}}`;
  }
  if (isNum(value)) {
    if (Number.isNaN(value)) return 'nan';
    if (value === Infinity) return 'inf';
    if (value === -Infinity) return '-inf';
  }
  return String(value);
}

