/**
 * The handful of Python operators the validator leans on, with Python's error
 * behaviour: `len()`, `in`, `==`, `>`/`<`, iteration and `sorted()`.
 */

import { TypeError_, ValueError } from './errors.mjs';
import { isBool, isDict, isList, isNum, isStr, keysOf, typeName } from './values.mjs';

/** `len(value)` — strings are measured in code points, like Python `str`. */
export function pyLen(value) {
  if (isStr(value)) {
    let length = 0;
    for (const _ of value) length += 1;
    return length;
  }
  if (isList(value)) return value.length;
  if (isDict(value)) return keysOf(value).length;
  throw new TypeError_(`object of type '${typeName(value)}' has no len()`);
}

/** `iter(value)` as an array — dicts iterate their keys, strings their chars. */
export function pyIter(value) {
  if (isList(value)) return value.slice();
  if (isDict(value)) return keysOf(value);
  if (isStr(value)) return [...value];
  throw new TypeError_(`'${typeName(value)}' object is not iterable`);
}

/** `item in container`. */
export function pyIn(item, container) {
  if (isDict(container)) {
    // Only `str` keys exist in decoded JSON, so nothing else can ever hash equal.
    return isStr(item) && Object.prototype.hasOwnProperty.call(container, item);
  }
  if (isList(container)) return container.some((each) => pyEq(each, item));
  if (isStr(container)) {
    if (!isStr(item)) {
      throw new TypeError_(
        `'in <string>' requires string as left operand, not ${typeName(item)}`,
      );
    }
    return container.includes(item);
  }
  throw new TypeError_(`argument of type '${typeName(container)}' is not iterable`);
}

/**
 * `one == two`.  Note that Python's numeric tower makes `True == 1` true; the
 * JSON Schema code deliberately avoids that with `equal()` (see
 * ../jsonschema/equality.mjs), but plain `==` still shows up in a few places.
 */
export function pyEq(one, two) {
  if (one === two) return true;
  // `json.loads` hands out one shared NaN object, so `nan is nan` holds and
  // `[NaN, NaN]` counts as a duplicate for `uniqueItems`.
  if (isNum(one) && isNum(two)) {
    return (Number.isNaN(one) && Number.isNaN(two)) || one === two;
  }
  if (isBool(one) || isBool(two)) {
