/**
 * `json.loads` for the subset of behaviour the CLI depends on.
 *
 * `JSON.parse` is close but not equal to CPython's decoder, and the two
 * differences both show up in practice:
 *
 *   - Python accepts the `NaN`, `Infinity` and `-Infinity` literals (and hands
 *     out one shared object for each, which makes `NaN is NaN` — and therefore
 *     `{"const": NaN}` against `NaN` — succeed).
 *   - Python tells `int` literals from `float` literals, which `multipleOf`
 *     depends on, and iterates object members in insertion order.
 *
 * Recording that extra information is why this is a hand written parser rather
 * than a `JSON.parse` call.
 */

import { JSONDecodeError } from './errors.mjs';
import { attachMeta } from './values.mjs';

const WHITESPACE = new Set([' ', '\t', '\n', '\r']);

const ESCAPES = {
  '"': '"',
  '\\': '\\',
  '/': '/',
  b: '\b',
  f: '\f',
  n: '\n',
  r: '\r',
  t: '\t',
};

const NUMBER = /^-?(?:0|[1-9]\d*)(\.\d+)?([eE][-+]?\d+)?/;

class Decoder {
  constructor(text) {
    this.text = text;
    this.pos = 0;
  }

  error(msg, pos = this.pos) {
    return new JSONDecodeError(msg, this.text, pos);
  }

  skipWhitespace() {
    while (this.pos < this.text.length && WHITESPACE.has(this.text[this.pos])) this.pos += 1;
  }

  decode() {
    this.skipWhitespace();
    const value = this.parseValue();
    this.skipWhitespace();
    if (this.pos !== this.text.length) throw this.error('Extra data');
    return value;
  }

  parseValue() {
    if (this.pos >= this.text.length) throw this.error('Expecting value');
    const char = this.text[this.pos];
    if (char === '{') return this.parseObject();
    if (char === '[') return this.parseArray();
    if (char === '"') return this.parseString();
    for (const [literal, value] of [
      ['true', true],
      ['false', false],
      ['null', null],
      ['NaN', NaN],
      ['Infinity', Infinity],
      ['-Infinity', -Infinity],
    ]) {
      if (this.text.startsWith(literal, this.pos)) {
        this.pos += literal.length;
        return value;
      }
    }
    const match = NUMBER.exec(this.text.slice(this.pos));
    if (match) {
      this.pos += match[0].length;
      // `match[1]`/`match[2]` are the fraction/exponent parts: their presence is
      // exactly what makes CPython produce a `float` instead of an `int`.
      this.lastNumberWasFloat = Boolean(match[1] || match[2]);
      return Number(match[0]);
    }
    throw this.error('Expecting value');
  }

  parseString() {
    const start = this.pos;
    this.pos += 1; // opening quote
    let out = '';
    for (;;) {
      if (this.pos >= this.text.length) {
        throw this.error('Unterminated string starting at', start);
      }
      const char = this.text[this.pos];
      if (char === '"') {
