/**
 * `re.search` with Python semantics on top of `RegExp`.
 *
 * The two engines agree on most patterns but disagree on the ones JSON Schema
 * authors actually write:
 *
 *   Python                              JavaScript
 *   `\d` `\w` `\s` are Unicode aware    ASCII only
 *   `$` also matches before a final \n  end of input only
 *   `\A` / `\Z`                         not supported
 *   `(?P<name>…)` / `(?P=name)`         `(?<name>…)` / `\k<name>`
 *   `(?i)` leading inline flags         flags live outside the pattern
 *   a lone `{`, `}` or `]` is literal   SyntaxError under the `u` flag
 *
 * Patterns are translated once and cached.  Anything Python rejects (`"("`,
 * `"\q"`, …) has to raise here too, because the reference implementation lets
 * `re.error` escape.
 */

import { ReError } from './errors.mjs';

// Python's `\w` is "alphanumeric or underscore" over the whole of Unicode and
// `\d` is the Nd category; `\s` is Python's `str.isspace()` set, which includes
// the C1 separators but — unlike JavaScript — not U+FEFF.
const WORD = '\\p{L}\\p{N}_';
const SPACE = '\\t\\n\\v\\f\\r \\x1c-\\x1f\\x85\\u00a0\\u1680\\u2000-\\u200a'
  + '\\u2028\\u2029\\u202f\\u205f\\u3000';

const CLASS_ESCAPES = {
  d: { inClass: '\\p{Nd}', outside: '\\p{Nd}' },
  D: { inClass: '\\P{Nd}', outside: '\\P{Nd}' },
  w: { inClass: WORD, outside: `[${WORD}]` },
  W: { inClass: `\\W`, outside: `[^${WORD}]` },
  s: { inClass: SPACE, outside: `[${SPACE}]` },
  S: { inClass: '\\S', outside: `[^${SPACE}]` },
};

// Python's `\b` uses the Unicode `\w` definition, so it has to be spelled out.
const WORD_BOUNDARY = `(?:(?<=[${WORD}])(?![${WORD}])|(?<![${WORD}])(?=[${WORD}]))`;
const NOT_WORD_BOUNDARY = `(?:(?<=[${WORD}])(?=[${WORD}])|(?<![${WORD}])(?![${WORD}]))`;

const QUANTIFIER = /^\{\d*(,\d*)?\}/;
const INLINE_FLAGS = /^\(\?([aiLmsux]+)\)/;

const cache = new Map();

function escapeLiteral(char) {
  return /[\\^$.*+?()[\]{}|/]/.test(char) ? `\\${char}` : char;
}

function translate(pattern) {
  if (typeof pattern !== 'string') {
    throw new ReError('first argument must be string or compiled pattern');
  }

  let flags = 'u';
  let source = pattern;

  // Global inline flags, which Python only allows at the very start.
  const inline = INLINE_FLAGS.exec(source);
  if (inline) {
    source = source.slice(inline[0].length);
    if (inline[1].includes('i')) flags += 'i';
    if (inline[1].includes('s')) flags += 's';
    if (inline[1].includes('m')) flags += 'm';
  }
  const multiline = flags.includes('m');

  let out = '';
  let inClass = false;
  let groupDepth = 0;
  let index = 0;

  while (index < source.length) {
    const char = source[index];

    if (char === '\\') {
      const next = source[index + 1];
      index += 2;
      if (next === undefined) throw new ReError('bad escape (end of pattern)');
      if (Object.prototype.hasOwnProperty.call(CLASS_ESCAPES, next)) {
        out += inClass ? CLASS_ESCAPES[next].inClass : CLASS_ESCAPES[next].outside;
      } else if (next === 'A') {
        out += inClass ? 'A' : '(?<![\\s\\S])';
      } else if (next === 'Z') {
        out += inClass ? 'Z' : '(?![\\s\\S])';
      } else if (next === 'b' && !inClass) {
        out += WORD_BOUNDARY;
      } else if (next === 'B' && !inClass) {
        out += NOT_WORD_BOUNDARY;
      } else if (next === 'U') {
        const hex = source.slice(index, index + 8);
