/**
 * The slice of `fractions.Fraction` that `multipleOf` needs.
 *
 * When `instance / multipleOf` overflows to infinity the reference
 * implementation falls back to exact rational arithmetic and asks whether the
 * quotient's denominator is 1.  Every finite double is exactly `mantissa *
 * 2**exponent`, so the same question can be answered with `BigInt`s.
 */

import { OverflowError, ValueError, ZeroDivisionError } from './errors.mjs';

const buffer = new DataView(new ArrayBuffer(8));

/** Exact `numerator / denominator` (both positive-denominator) of a double. */
export function fractionOf(value) {
  if (Number.isNaN(value)) throw new ValueError('cannot convert NaN to integer ratio');
  if (!Number.isFinite(value)) {
    throw new OverflowError('cannot convert Infinity to integer ratio');
  }
  if (Number.isInteger(value)) return { numerator: BigInt(value), denominator: 1n };

  buffer.setFloat64(0, value);
  const bits = buffer.getBigUint64(0);
  const sign = bits >> 63n ? -1n : 1n;
  const biasedExponent = Number((bits >> 52n) & 0x7ffn);
  const rawMantissa = bits & 0xfffffffffffffn;

  // Subnormals have no implicit leading bit and a fixed exponent.
  const mantissa = biasedExponent === 0 ? rawMantissa : rawMantissa | 0x10000000000000n;
  const exponent = (biasedExponent === 0 ? -1074 : biasedExponent - 1075);

  let numerator = sign * mantissa;
  let denominator = 1n;
  if (exponent >= 0) numerator <<= BigInt(exponent);
  else denominator = 1n << BigInt(-exponent);

  return reduce(numerator, denominator);
}

function reduce(numerator, denominator) {
  let a = numerator < 0n ? -numerator : numerator;
  let b = denominator;
  while (b) {
    [a, b] = [b, a % b];
  }
  const divisor = a || 1n;
  return { numerator: numerator / divisor, denominator: denominator / divisor };
}

/** True when `dividend / divisor` is an exact integer (denominator == 1). */
export function quotientIsIntegral(dividend, divisor) {
  const left = fractionOf(dividend);
  const right = fractionOf(divisor);
  const numerator = left.numerator * right.denominator;
  const denominator = left.denominator * right.numerator;
  if (denominator === 0n) throw new ZeroDivisionError('division by zero');
  return numerator % denominator === 0n;
}

