/**
 * `urllib.parse` helpers: `urljoin`, `urldefrag` and `unquote`.
 *
 * `new URL()` cannot stand in for these because reference resolution regularly
 * starts from a relative — or empty — base URI, which is exactly the case the
 * WHATWG parser rejects.
 */

// Schemes urllib is willing to resolve relative references against.  Anything
// else (`urn:`, `mailto:`, …) makes Python return the reference untouched.
const USES_RELATIVE = new Set([
  '', 'ftp', 'http', 'gopher', 'nntp', 'imap', 'wais', 'file', 'https', 'shttp',
  'mms', 'prospero', 'rtsp', 'rtspu', 'sftp', 'svn', 'svn+ssh', 'ws', 'wss',
]);

const USES_NETLOC = new Set([
  '', 'ftp', 'http', 'gopher', 'nntp', 'telnet', 'imap', 'wais', 'file', 'mms',
  'https', 'shttp', 'snews', 'prospero', 'rtsp', 'rtspu', 'rsync', 'svn',
  'svn+ssh', 'sftp', 'nfs', 'git', 'git+ssh', 'ws', 'wss', 'itms-services',
]);

const SCHEME = /^([a-zA-Z][a-zA-Z0-9+\-.]*):/;

function urlparse(url) {
  let rest = url;
  let scheme = '';
  const schemeMatch = SCHEME.exec(rest);
  if (schemeMatch) {
    scheme = schemeMatch[1].toLowerCase();
    rest = rest.slice(schemeMatch[0].length);
  }

  let fragment = '';
  const hash = rest.indexOf('#');
  if (hash !== -1) {
    fragment = rest.slice(hash + 1);
    rest = rest.slice(0, hash);
  }

  let query = '';
  const question = rest.indexOf('?');
  if (question !== -1) {
    query = rest.slice(question + 1);
    rest = rest.slice(0, question);
  }

  let netloc = '';
  if (rest.startsWith('//')) {
    const end = ((index) => (index === -1 ? rest.length : index))(
      rest.indexOf('/', 2),
    );
    netloc = rest.slice(2, end);
    rest = rest.slice(end);
  }

  return { scheme, netloc, path: rest, query, fragment };
}

function urlunparse({ scheme, netloc, path, query, fragment }) {
  let url = '';
  if (scheme) url += `${scheme}:`;
  if (netloc || (scheme && path.startsWith('//'))) url += `//${netloc}`;
  url += path;
  if (query) url += `?${query}`;
  if (fragment) url += `#${fragment}`;
  return url;
}

/** `urllib.parse.urljoin(base, url)`. */
export function urljoin(base, url) {
  if (!base) return url;
  if (!url) return base;

  const b = urlparse(base);
  const u = urlparse(url);
  const scheme = u.scheme || b.scheme;

  if (scheme !== b.scheme || !USES_RELATIVE.has(scheme)) return url;

  if (USES_NETLOC.has(scheme) && u.netloc) {
    return urlunparse({ ...u, scheme });
  }
  const netloc = u.netloc || b.netloc;

  if (!u.path) {
    return urlunparse({
      scheme,
      netloc,
      path: b.path,
      query: u.query || b.query,
      fragment: u.fragment,
    });
  }

  let segments;
  if (u.path.startsWith('/')) {
    segments = u.path.split('/');
  } else {
    const baseSegments = b.path.split('/');
    if (baseSegments[baseSegments.length - 1] !== '') baseSegments.pop();
    segments = baseSegments.concat(u.path.split('/'));
    const middle = segments.slice(1, -1).filter((segment) => segment !== '');
    segments = [segments[0], ...middle, segments[segments.length - 1]];
  }

  const resolved = [];
  for (const segment of segments) {
    if (segment === '..') resolved.pop();
    else if (segment !== '.') resolved.push(segment);
  }
  const last = segments[segments.length - 1];
  if (last === '.' || last === '..') resolved.push('');

  return urlunparse({
    scheme,
    netloc,
    path: resolved.join('/') || '/',
    query: u.query,
    fragment: u.fragment,
  });
