/** `urllib.parse.urldefrag(url)` → `[url without fragment, fragment]`. */
export function urldefrag(url) {
  const hash = url.indexOf('#');
  if (hash === -1) return [url, ''];
  return [url.slice(0, hash), url.slice(hash + 1)];
}

const decoder = new TextDecoder('utf-8', { fatal: false });

/** `urllib.parse.unquote(string)` — percent-decoding, replacing bad bytes. */
export function unquote(string) {
  if (!string.includes('%')) return string;
  let out = '';
  let index = 0;
  while (index < string.length) {
    if (string[index] === '%' && /^[0-9a-fA-F]{2}$/.test(string.slice(index + 1, index + 3))) {
      const bytes = [];
      while (
        string[index] === '%'
        && /^[0-9a-fA-F]{2}$/.test(string.slice(index + 1, index + 3))
      ) {
        bytes.push(parseInt(string.slice(index + 1, index + 3), 16));
        index += 3;
      }
      out += decoder.decode(new Uint8Array(bytes));
      continue;
    }
    out += string[index];
    index += 1;
  }
  return out;
}

