/**
 * `jsonschema.exceptions`.
 *
 * `ValidationError`s are the things being counted.  `UnknownType` and
 * `_WrappedReferencingError` are raised, not yielded, and abort the run.
 */

import { repr } from '../python/values.mjs';

export class ValidationError {
  constructor(message, { context = [], path = [], schemaPath = [] } = {}) {
    this.message = message;
    this.context = context;
    this.path = path;
    this.schemaPath = schemaPath;
  }
}

export class UnknownType extends Error {
  constructor(type, instance) {
    super(`Unknown type ${repr(type)} for validator with schema`);
    this.name = 'UnknownType';
    this.pyType = 'jsonschema.exceptions.UnknownType';
    this.type = type;
    this.instance = instance;
  }

  toString() {
    return `${this.pyType}: ${this.message}`;
  }
}

export class WrappedReferencingError extends Error {
  constructor(cause) {
    super(cause.toString());
    this.name = 'WrappedReferencingError';
    this.pyType = 'jsonschema.exceptions._WrappedReferencingError';
    this.cause = cause;
  }

  toString() {
    return `${this.pyType}: ${this.cause.toString()}`;
  }
}

