/**
 * `jsonschema._utils`: `unbool`, `equal` and `uniq`.
 *
 * JSON Schema has to undo Python's "bool is an int" inheritance, otherwise
 * `{"enum": [1]}` would accept `true`.  `unbool` swaps booleans for sentinels
 * that compare equal to nothing else, and `equal` recurses into arrays and
 * objects doing the same.
 */

import { isDict, isList, isNum, isStr, keysOf } from '../python/values.mjs';

const TRUE = Symbol('True');
const FALSE = Symbol('False');

/** `_utils.unbool` — booleans become sentinels, everything else is itself. */
export function unbool(element) {
  if (element === true) return TRUE;
  if (element === false) return FALSE;
  return element;
}

/** `_utils.equal` — equality that keeps `True` and `1` apart. */
export function equal(one, two) {
  if (one === two) return true;
  // `json.loads` reuses a single NaN object, so `nan is nan` is true in Python
  // and `{"const": NaN}` accepts `NaN`.
  if (isNum(one) && isNum(two) && Number.isNaN(one) && Number.isNaN(two)) return true;
  if (isStr(one) || isStr(two)) return one === two;
  if (isList(one) && isList(two)) {
    return one.length === two.length && one.every((each, index) => equal(each, two[index]));
  }
  if (isDict(one) && isDict(two)) {
    const keys = keysOf(one);
    if (keys.length !== keysOf(two).length) return false;
    return keys.every(
      (key) => Object.prototype.hasOwnProperty.call(two, key) && equal(one[key], two[key]),
    );
  }
  return unbool(one) === unbool(two);
}

/**
 * A hashable stand-in for the scalars, so the common case does not need the
 * quadratic comparison below.  Containers get `null` and fall back.
 */
function scalarKey(value) {
  if (value === null) return 'null';
  if (value === true) return 'true';
  if (value === false) return 'false';
  if (isStr(value)) return `s${value}`;
  if (isNum(value)) return Number.isNaN(value) ? 'nan' : `n${value}`;
  return null;
}

/**
 * `_utils.uniq`.
 *
 * The reference implementation sorts the (unbooled) elements and compares
 * neighbours, falling back to a quadratic scan when the elements are not
 * mutually orderable.  Both paths compare with `equal`, so both answer the same
 * question: "are any two elements equal?".
 */
export function uniq(container) {
  const seenScalars = new Set();
  const containers = [];
  for (const element of container) {
    const key = scalarKey(element);
    if (key === null) {
      if (containers.some((each) => equal(each, element))) return false;
      containers.push(element);
    } else {
      if (seenScalars.has(key)) return false;
      seenScalars.add(key);
    }
  }
  return true;
}

