const numeric = (value) => (isBool(value) ? (value ? 1 : 0) : value);

const apply = (left, right, operator) => {
  switch (operator) {
    case '>': return left > right;
    case '<': return left < right;
    case '>=': return left >= right;
    default: return left <= right;
  }
};

/** `one < two` / `one > two` / `>=` / `<=`, raising for unorderable pairs. */
export function pyCompare(one, two, operator) {
  const left = numeric(one);
  const right = numeric(two);
  if ((isNum(left) && isNum(right)) || (isStr(left) && isStr(right))) {
    return apply(left, right, operator);
  }
  if (isList(left) && isList(right)) {
    const shared = Math.min(left.length, right.length);
    for (let index = 0; index < shared; index += 1) {
      if (!pyEq(left[index], right[index])) {
        const strict = operator[0] === '>' ? '>' : '<';
        return pyCompare(left[index], right[index], strict);
      }
    }
    return apply(left.length, right.length, operator);
  }
  throw new TypeError_(
    `'${operator}' not supported between instances of `
    + `'${typeName(one)}' and '${typeName(two)}'`,
  );
}

export const pyGt = (one, two) => pyCompare(one, two, '>');
export const pyLt = (one, two) => pyCompare(one, two, '<');
export const pyGe = (one, two) => pyCompare(one, two, '>=');
export const pyLe = (one, two) => pyCompare(one, two, '<=');

/** `one % two` for numbers, with Python's zero/type errors. */
export function pyMod(one, two) {
  const left = numeric(one);
  const right = numeric(two);
  if (!isNum(left) || !isNum(right)) {
    throw new TypeError_(
      `unsupported operand type(s) for %: '${typeName(one)}' and '${typeName(two)}'`,
    );
  }
  if (right === 0) {
    throw new ZeroDivisionError(
      Number.isInteger(right) ? 'integer modulo by zero' : 'float modulo',
    );
  }
  return left % right;
}

/** `one / two` for numbers, with Python's type errors. */
export function pyTrueDiv(one, two) {
  const left = numeric(one);
  const right = numeric(two);
  if (!isNum(left) || !isNum(right)) {
    throw new TypeError_(
      `unsupported operand type(s) for /: '${typeName(one)}' and '${typeName(two)}'`,
    );
  }
  if (right === 0) throw new ZeroDivisionError('float division by zero');
  return left / right;
}

