/**
 * The handful of Python operators the validator leans on, with Python's error
 * behaviour: `len()`, `in`, `==`, `>`/`<`, iteration and `sorted()`.
 */

import { OverflowError, TypeError_, ValueError } from './errors.mjs';
import { isBool, isDict, isList, isNum, isStr, keysOf, typeName } from './values.mjs';

/** `len(value)` — strings are measured in code points, like Python `str`. */
export function pyLen(value) {
  if (isStr(value)) {
    let length = 0;
    for (const _ of value) length += 1;
    return length;
  }
  if (isList(value)) return value.length;
  if (isDict(value)) return keysOf(value).length;
  throw new TypeError_(`object of type '${typeName(value)}' has no len()`);
}

/** `iter(value)` as an array — dicts iterate their keys, strings their chars. */
export function pyIter(value) {
  if (isList(value)) return value.slice();
  if (isDict(value)) return keysOf(value);
  if (isStr(value)) return [...value];
  throw new TypeError_(`'${typeName(value)}' object is not iterable`);
}

/** `item in container`. */
export function pyIn(item, container) {
  if (isDict(container)) {
    // Only `str` keys exist in decoded JSON, so nothing else can ever hash equal.
    return isStr(item) && Object.prototype.hasOwnProperty.call(container, item);
  }
  if (isList(container)) return container.some((each) => pyEq(each, item));
  if (isStr(container)) {
    if (!isStr(item)) {
      throw new TypeError_(
        `'in <string>' requires string as left operand, not ${typeName(item)}`,
      );
    }
    return container.includes(item);
  }
  throw new TypeError_(`argument of type '${typeName(container)}' is not iterable`);
}

/**
 * `one == two`.  Note that Python's numeric tower makes `True == 1` true; the
 * JSON Schema code deliberately avoids that with `equal()` (see
 * ../jsonschema/equality.mjs), but plain `==` still shows up in a few places.
 */
export function pyEq(one, two) {
  if (one === two) return true;
  // `json.loads` hands out one shared NaN object, so `nan is nan` holds and
  // `[NaN, NaN]` counts as a duplicate for `uniqueItems`.
  if (isNum(one) && isNum(two)) {
    return (Number.isNaN(one) && Number.isNaN(two)) || one === two;
  }
  if (isBool(one) || isBool(two)) {
    const left = isBool(one) ? (one ? 1 : 0) : one;
    const right = isBool(two) ? (two ? 1 : 0) : two;
    return isNum(left) && isNum(right) && left === right;
  }
  if (isList(one) && isList(two)) {
    return one.length === two.length && one.every((each, index) => pyEq(each, two[index]));
  }
  if (isDict(one) && isDict(two)) {
    const keys = keysOf(one);
    if (keys.length !== keysOf(two).length) return false;
    return keys.every(
      (key) => Object.prototype.hasOwnProperty.call(two, key) && pyEq(one[key], two[key]),
    );
  }
  return false;
}

const numeric = (value) => (isBool(value) ? (value ? 1 : 0) : value);

/** `one < two` / `one > two`, raising `TypeError` for unorderable pairs. */
export function pyCompare(one, two, operator) {
  const left = numeric(one);
  const right = numeric(two);
  if (isNum(left) && isNum(right)) {
    return operator === '>' ? left > right : left < right;
  }
  if (isStr(left) && isStr(right)) {
    return operator === '>' ? left > right : left < right;
  }
  if (isList(left) && isList(right)) {
    const shared = Math.min(left.length, right.length);
    for (let index = 0; index < shared; index += 1) {
      if (!pyEq(left[index], right[index])) {
        return pyCompare(left[index], right[index], operator);
      }
    }
    return operator === '>' ? left.length > right.length : left.length < right.length;
  }
  throw new TypeError_(
    `'${operator}' not supported between instances of `
    + `'${typeName(one)}' and '${typeName(two)}'`,
  );
}

export const pyGt = (one, two) => pyCompare(one, two, '>');
export const pyLt = (one, two) => pyCompare(one, two, '<');

/**
 * `sorted(values)`.  Only used by `uniqueItems`, which relies on the
 * `TypeError` raised for unorderable element pairs, so the comparison — not the
 * exact ordering algorithm — is what matters here.
 */
export function pySorted(values) {
  const sorted = values.slice();
  // Insertion sort: every out-of-order pair is compared, which is what makes
  // mixed-type containers raise the way CPython's timsort does.
  for (let i = 1; i < sorted.length; i += 1) {
    const value = sorted[i];
    let j = i - 1;
    while (j >= 0 && pyLt(value, sorted[j])) {
      sorted[j + 1] = sorted[j];
      j -= 1;
    }
    sorted[j + 1] = value;
  }
  return sorted;
}

/** `int(value)` for a float, with Python's error behaviour. */
export function pyIntOfFloat(value) {
  if (Number.isNaN(value)) throw new ValueError('cannot convert float NaN to integer');
  if (!Number.isFinite(value)) {
    throw new OverflowError('cannot convert float infinity to integer');
  }
  return Math.trunc(value);
}

