/**
 * `type`, `enum` and `const`.
 */

import { isStr } from '../../python/values.mjs';
import { repr } from '../../python/values.mjs';
import { pyIter } from '../../python/ops.mjs';
import { equal } from '../equality.mjs';
import { ValidationError } from '../exceptions.mjs';

/** `_utils.ensure_list` — a bare string means a single type. */
const ensureList = (types) => (isStr(types) ? [types] : pyIter(types));

export function* type(validator, types, instance) {
  const candidates = ensureList(types);
  if (!candidates.some((each) => validator.isType(instance, each))) {
    yield new ValidationError(`${repr(instance)} is not of type ${candidates.map(repr).join(', ')}`);
  }
}

export function* enum_(validator, enums, instance) {
  const candidates = pyIter(enums);
  if (candidates.every((each) => !equal(each, instance))) {
    yield new ValidationError(`${repr(instance)} is not one of ${repr(enums)}`);
  }
}

export function* const_(validator, constant, instance) {
  if (!equal(constant, instance)) {
    yield new ValidationError(`${repr(constant)} was expected`);
  }
}

/**
 * `format` is a no-op without a format checker, and `Draft7Validator(schema)`
 * is constructed without one — annotations only, never assertions.
 */
export function* format() {
  // Intentionally empty.
}

/** draft-03's `type`, where a type entry may itself be a schema. */
export function* typeDraft3(validator, types, instance) {
  const candidates = ensureList(types);
  const allErrors = [];
  for (const [index, each] of candidates.entries()) {
    if (validator.isType(each, 'object')) {
      const errors = [...validator.descend(instance, each, { schemaPath: index })];
      if (errors.length === 0) return;
      allErrors.push(...errors);
    } else if (validator.isType(instance, each)) {
      return;
    }
  }
  yield new ValidationError(
    `${repr(instance)} is not of type ${candidates.map(repr).join(', ')}`,
    { context: allErrors },
  );
}

/** draft-03's `disallow`. */
export function* disallowDraft3(validator, disallow, instance) {
  for (const each of ensureList(disallow)) {
    if (validator.evolve({ schema: each }).isValid(instance)) {
      yield new ValidationError(`${repr(instance)} is disallowed for ${repr(instance)}`);
    }
  }
}

/** draft-03's `extends`. */
export function* extendsDraft3(validator, extendsValue, instance) {
  if (validator.isType(extendsValue, 'object')) {
    yield* validator.descend(instance, extendsValue);
    return;
  }
  for (const [index, subschema] of pyIter(extendsValue).entries()) {
    yield* validator.descend(instance, subschema, { schemaPath: index });
  }
}

