/**
 * The numeric keywords.
 *
 * `multipleOf` is the one with teeth: the reference implementation branches on
 * whether the keyword's value is a Python `float` or an `int`, uses float
 * division for the former and `%` for the latter, and only falls back to exact
 * rational arithmetic when the division overflows to infinity.  All three paths
 * are observable — `{"multipleOf": 3}` and `{"multipleOf": 3.0}` disagree about
 * `1e30`, and `NaN`/`Infinity` instances make it raise.
 */

import { OverflowError } from '../../python/errors.mjs';
import { quotientIsIntegral } from '../../python/fraction.mjs';
import { pyGe, pyGt, pyIntOfFloat, pyLe, pyLt, pyMod, pyTrueDiv } from '../../python/ops.mjs';
import { isFloatMember, repr } from '../../python/values.mjs';
import { ValidationError } from '../exceptions.mjs';

function* checkMultiple(dB, instance, isFloat) {
  let failed;
  if (isFloat) {
    const quotient = pyTrueDiv(instance, dB);
    try {
      failed = pyIntOfFloat(quotient) !== quotient;
    } catch (error) {
      if (!(error instanceof OverflowError)) throw error;
      // The quotient overflowed; `Fraction` answers the question exactly.
      failed = !quotientIsIntegral(instance, dB);
    }
  } else {
    const remainder = pyMod(instance, dB);
    failed = !(remainder === 0); // NaN is truthy in Python
  }

  if (failed) yield new ValidationError(`${repr(instance)} is not a multiple of ${repr(dB)}`);
}

export function* multipleOf(validator, dB, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  yield* checkMultiple(dB, instance, isFloatMember(schema, 'multipleOf'));
}

export function* maximum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyGt(instance, bound)) {
    yield new ValidationError(`${repr(instance)} is greater than the maximum of ${repr(bound)}`);
  }
}

export function* minimum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyLt(instance, bound)) {
    yield new ValidationError(`${repr(instance)} is less than the minimum of ${repr(bound)}`);
  }
}

export function* exclusiveMaximum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyGe(instance, bound)) {
    yield new ValidationError(
      `${repr(instance)} is greater than or equal to the maximum of ${repr(bound)}`,
    );
  }
}

export function* exclusiveMinimum(validator, bound, instance) {
  if (!validator.isType(instance, 'number')) return;
  if (pyLe(instance, bound)) {
    yield new ValidationError(
      `${repr(instance)} is less than or equal to the minimum of ${repr(bound)}`,
    );
  }
}

/** draft-03/04 read `exclusiveMaximum` as a boolean modifier of `maximum`. */
export function* maximumDraft3Draft4(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  const exclusive = schema.exclusiveMaximum ?? false;
  const failed = exclusive ? pyGe(instance, bound) : pyGt(instance, bound);
  if (failed) {
    yield new ValidationError(`${repr(instance)} is greater than the maximum of ${repr(bound)}`);
  }
}

export function* minimumDraft3Draft4(validator, bound, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  const exclusive = schema.exclusiveMinimum ?? false;
  const failed = exclusive ? pyLe(instance, bound) : pyLt(instance, bound);
  if (failed) {
    yield new ValidationError(`${repr(instance)} is less than the minimum of ${repr(bound)}`);
  }
}

/** draft-03's `divisibleBy`. */
export function* divisibleBy(validator, dB, instance, schema) {
  yield* multipleOf(validator, dB, instance, schema);
}

