/**
 * The string keywords.  Lengths are code point counts, and `pattern` is a
 * Python `re.search`, not a JavaScript one — see ../../python/re.mjs.
 */

import { pyGt, pyLen, pyLt } from '../../python/ops.mjs';
import { repr } from '../../python/values.mjs';
import { search } from '../../python/re.mjs';
import { ValidationError } from '../exceptions.mjs';

export function* maxLength(validator, bound, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (pyGt(pyLen(instance), bound)) {
    yield new ValidationError(`${repr(instance)} is too long`);
  }
}

export function* minLength(validator, bound, instance) {
  if (!validator.isType(instance, 'string')) return;
  if (pyLt(pyLen(instance), bound)) {
    yield new ValidationError(`${repr(instance)} is too short`);
  }
}

export function* pattern(validator, patrn, instance) {
  // The pattern is only compiled for string instances, so an invalid regex in a
  // schema that never sees a string goes unnoticed — as it does in Python.
  if (!validator.isType(instance, 'string')) return;
  if (!search(patrn, instance)) {
    yield new ValidationError(`${repr(instance)} does not match ${repr(patrn)}`);
  }
}

