/**
 * The array keywords.
 *
 * `items`/`additionalItems` keep their draft-07 shape: `items` may be a schema
 * or a tuple of schemas, and `additionalItems` only applies in the tuple case —
 * `{"items": true, "additionalItems": false}` makes the reference
 * implementation raise `TypeError` (`len(True)`), which is reproduced here.
 */

import { pyGt, pyLen, pyLt } from '../../python/ops.mjs';
import { repr } from '../../python/values.mjs';
import { uniq } from '../equality.mjs';
import { ValidationError } from '../exceptions.mjs';

export function* items(validator, itemsValue, instance) {
  if (!validator.isType(instance, 'array')) return;

  if (validator.isType(itemsValue, 'array')) {
    const shared = Math.min(instance.length, itemsValue.length);
    for (let index = 0; index < shared; index += 1) {
      yield* validator.descend(instance[index], itemsValue[index], {
        path: index,
        schemaPath: index,
      });
    }
    return;
  }
  for (const [index, item] of instance.entries()) {
    yield* validator.descend(item, itemsValue, { path: index });
  }
}

/** draft-03/04 decide tuple-vs-schema the other way around. */
export function* itemsDraft3Draft4(validator, itemsValue, instance) {
  if (!validator.isType(instance, 'array')) return;

  if (validator.isType(itemsValue, 'object')) {
    for (const [index, item] of instance.entries()) {
      yield* validator.descend(item, itemsValue, { path: index });
    }
    return;
  }
  const shared = Math.min(instance.length, pyLen(itemsValue));
  for (let index = 0; index < shared; index += 1) {
    yield* validator.descend(instance[index], itemsValue[index], {
      path: index,
      schemaPath: index,
    });
  }
}

export function* additionalItems(validator, aI, instance, schema) {
  const declared = Object.prototype.hasOwnProperty.call(schema, 'items') ? schema.items : {};
  if (!validator.isType(instance, 'array') || validator.isType(declared, 'object')) return;

  // `len()` of a boolean `items` raises, exactly as in the reference code.
  const lenItems = pyLen(declared);
  if (validator.isType(aI, 'object')) {
    for (let index = lenItems; index < instance.length; index += 1) {
      yield* validator.descend(instance[index], aI, { path: index });
    }
    return;
  }
  const empty = aI === false || aI === 0 || aI === '' || aI === null
    || (Array.isArray(aI) && aI.length === 0);
  if (empty && instance.length > lenItems) {
    yield new ValidationError(
      `Additional items are not allowed (${instance.slice(lenItems).map(repr).join(', ')} `
      + 'unexpected)',
    );
  }
}

export function* maxItems(validator, bound, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (pyGt(instance.length, bound)) {
    yield new ValidationError(`${repr(instance)} is too long`);
  }
}

export function* minItems(validator, bound, instance) {
  if (!validator.isType(instance, 'array')) return;
  if (pyLt(instance.length, bound)) {
    yield new ValidationError(`${repr(instance)} is too short`);
  }
}

export function* uniqueItems(validator, uI, instance) {
  if (uI && validator.isType(instance, 'array') && !uniq(instance)) {
    yield new ValidationError(`${repr(instance)} has non-unique elements`);
  }
}

/** draft-06/07 `contains`: one error for the whole array, never per element. */
export function* contains(validator, containsValue, instance) {
  if (!validator.isType(instance, 'array')) return;
  const matched = instance.some(
    (element) => validator.evolve({ schema: containsValue }).isValid(element),
  );
  if (!matched) {
    yield new ValidationError(`None of ${repr(instance)} are valid under the given schema`);
  }
}

