/** `bool(value)` — Python truthiness (note `bool(nan)` is `True`). */
export function pyBool(value) {
  if (value === null || value === undefined) return false;
  if (isBool(value)) return value;
  if (isNum(value)) return value !== 0;
  if (isStr(value) || isList(value)) return value.length > 0;
  if (isDict(value)) return keysOf(value).length > 0;
  return true;
}
EOF
